-- TEST FIXTURE ONLY: predecessor schema from feature/v8.5.1-ai-local-news; not an installation script.
-- V8.5.1 new tables in existing V8.3 MySQL; never DROP tables
CREATE TABLE IF NOT EXISTS news_topics(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,district_id BIGINT UNSIGNED NOT NULL,title VARCHAR(200) NOT NULL,category ENUM('festival','tourism','transport','culture','other') DEFAULT 'festival',created_by VARCHAR(100) NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'draft',CONSTRAINT fk_v851_topic_district FOREIGN KEY(district_id) REFERENCES districts(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS news_sources(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,topic_id BIGINT UNSIGNED NOT NULL,organization VARCHAR(200) NOT NULL,source_title VARCHAR(300) NOT NULL,source_url VARCHAR(1024) NOT NULL,published_at DATETIME NOT NULL,CONSTRAINT fk_v851_source_topic FOREIGN KEY(topic_id) REFERENCES news_topics(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS news_facts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,topic_id BIGINT UNSIGNED NOT NULL,fact_key VARCHAR(100) NOT NULL,fact_type VARCHAR(30) NOT NULL,value_text TEXT NOT NULL,value_number DOUBLE NULL,status ENUM('candidate','verified','rejected') NOT NULL DEFAULT 'candidate',verified_by VARCHAR(100) NULL,verified_at DATETIME NULL,UNIQUE KEY uq_v851_fact(topic_id,fact_key),CONSTRAINT fk_v851_fact_topic FOREIGN KEY(topic_id) REFERENCES news_topics(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS news_fact_evidence(fact_id BIGINT UNSIGNED NOT NULL,source_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(fact_id,source_id),FOREIGN KEY(fact_id) REFERENCES news_facts(id),FOREIGN KEY(source_id) REFERENCES news_sources(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS news_drafts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,topic_id BIGINT UNSIGNED NOT NULL,title VARCHAR(300) NOT NULL,body_text LONGTEXT NOT NULL,model_name VARCHAR(100) NOT NULL,fact_snapshot_sha256 CHAR(64) NOT NULL,status ENUM('generated','in_review','changes_requested','approved','published') NOT NULL DEFAULT 'generated',created_by VARCHAR(100) NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(topic_id) REFERENCES news_topics(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS news_reviews(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,draft_id BIGINT UNSIGNED NOT NULL,reviewer_key VARCHAR(100) NOT NULL,check_passed BOOLEAN NOT NULL,comment TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(draft_id) REFERENCES news_drafts(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS news_claims(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,draft_id BIGINT UNSIGNED NOT NULL,sequence_no INT NOT NULL,statement_text TEXT NOT NULL,status ENUM('supported','unverified','contradicted') DEFAULT 'unverified',FOREIGN KEY(draft_id) REFERENCES news_drafts(id),UNIQUE KEY uq_v851_claim(draft_id,sequence_no)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS news_claim_facts(claim_id BIGINT UNSIGNED NOT NULL,fact_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(claim_id,fact_id),FOREIGN KEY(claim_id) REFERENCES news_claims(id),FOREIGN KEY(fact_id) REFERENCES news_facts(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS news_publications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,draft_id BIGINT UNSIGNED NOT NULL,topic_id BIGINT UNSIGNED NOT NULL,published_at DATETIME NULL,status ENUM('draft','published','unpublished') DEFAULT 'draft',FOREIGN KEY(draft_id) REFERENCES news_drafts(id),FOREIGN KEY(topic_id) REFERENCES news_topics(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS news_ai_usage(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,topic_id BIGINT UNSIGNED NOT NULL,draft_id BIGINT UNSIGNED NULL,model_name VARCHAR(100) NOT NULL,input_tokens INT NOT NULL DEFAULT 0,output_tokens INT NOT NULL DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(topic_id) REFERENCES news_topics(id),FOREIGN KEY(draft_id) REFERENCES news_drafts(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

